<script setup lang="ts">
import {ref,reactive,watch,onMounted} from 'vue';
import {systemApi,type ConnectionConfig,type ConnectionInput,type ConnectionTest,type DatabaseSettings,type RedisSettings,type HttpSettings} from '@/services/api';
import CmsConnectionReport from './CmsConnectionReport.vue';
type Section='database'|'redis'|'http';
const config=ref<ConnectionConfig|null>(null),busy=ref(''),error=ref('');
const forms=reactive<Record<Section,Record<string,string|number>>>({database:{},redis:{address:'127.0.0.1:6379',username:'',password:'',db:0,poolSize:100,minIdle:0,maxIdle:50,ttlSeconds:60},http:{}});
const feedback=reactive<Record<string,string>>({}),results=reactive<Partial<Record<Section,ConnectionTest>>>({});
const passwordAction=ref<'keep'|'replace'|'clear'>('keep'),showPassword=ref(false);
const initial=reactive<Record<string,string>>({});
const dbFields=[['connectSeconds','连接超时（秒）'],['readSeconds','读取超时（秒）'],['writeSeconds','写入超时（秒）'],['maxOpen','最大连接数'],['maxIdle','最大空闲连接'],['lifetimeSeconds','连接存活时间（秒）'],['idleSeconds','空闲回收时间（秒）']];
const redisFields=[['poolSize','最大连接数'],['minIdle','最小空闲连接'],['maxIdle','最大空闲连接'],['ttlSeconds','内容缓存时长（秒）']];
const httpFields=[['maxIdle','全局空闲连接'],['maxIdlePerHost','单域名空闲连接'],['maxPerHost','单域名最大连接'],['idleSeconds','空闲回收时间（秒）']];
const snapshot=(s:Section)=>JSON.stringify([forms[s],s==='redis'?passwordAction.value:'']);
function fill(v:ConnectionConfig){config.value=v;forms.database={...v.saved.database.settings};forms.http={...v.saved.http};if(v.saved.redis)forms.redis={...v.saved.redis.values,username:v.saved.redis.values.username||'',password:''};passwordAction.value='keep';for(const s of ['database','redis','http'] as Section[])initial[s]=snapshot(s);}
async function load(){if(busy.value)return;if(config.value&&(['database','redis','http'] as Section[]).some(s=>initial[s]!==snapshot(s))&&!window.confirm('重新读取会替换尚未保存的输入，是否继续？'))return;busy.value='load';error.value='';try{fill(await systemApi.connections());for(const s of ['database','redis','http'] as Section[]){delete results[s];delete feedback[s];}}catch(e){error.value=(e as Error).message;}finally{busy.value='';}}
function pending(s:Section){if(!config.value)return false;return JSON.stringify(config.value.active[s])!==JSON.stringify(config.value.saved[s]);}
function describe(s:Section){const a=config.value?.active;if(!a)return '';if(s==='redis')return a.redis?a.redis.values.address+' · DB '+a.redis.values.db:'尚未启用 Redis';if(s==='database')return a.database.mode==='mysql'?a.database.address+' / '+a.database.name:'本地文件存储';return a.http.timeoutSeconds+' 秒请求超时 · 单域名最多 '+a.http.maxPerHost+' 个连接';}
function input(s:Section):ConnectionInput{const values={...forms[s]};for(const k of Object.keys(values))if(!['address','username','password'].includes(k))values[k]=Number(values[k]);if(s==='redis'&&passwordAction.value!=='replace')delete values.password;return {section:s,values:values as unknown as DatabaseSettings|RedisSettings|HttpSettings,revision:config.value?.revision,passwordAction:s==='redis'?passwordAction.value:undefined};}
async function run(s:Section,save=false){if(busy.value||!config.value)return;busy.value=s+(save?'-save':'-test');error.value='';feedback[s]='';try{if(save){const v=await systemApi.saveConnections(input(s));config.value=v;if(s==='redis'){forms.redis={...v.saved.redis!.values,username:v.saved.redis!.values.username||'',password:''};passwordAction.value='keep';}initial[s]=snapshot(s);feedback[s]=pending(s)?'已写入服务器配置文件，重启运营服务后生效。':'已保存，当前运行参数一致。';}else{delete results[s];results[s]=await systemApi.testConnections(input(s));}}catch(e){feedback[s]=(e as Error).message;}finally{busy.value='';}}
for(const s of ['database','redis','http'] as Section[])watch(()=>snapshot(s),()=>{delete results[s];feedback[s]='';},{flush:'sync'});
onMounted(load);
</script>
<template><view class="connections-panel">
<view class="status-bar"><text><text class="status-dot" :class="{pending:config?.restartRequired}"></text>{{config?(config.restartRequired?'已保存配置中有待重启项目':'已读取服务器连接配置'):'正在读取连接配置'}}</text><button :disabled="!!busy" @click="load">{{busy==='load'?'读取中…':'重新读取'}}</button></view>
<text v-if="error" class="notice error" role="alert">{{error}}</text>
<text v-if="config?.restartRequired" class="notice pending-note">连接参数保存后需重启运营服务。下面的“当前运行”始终显示本进程实际使用的值。</text>
<template v-if="config">
<view v-for="s in (['database','redis','http'] as const)" :key="s" class="config-card">
<view class="card-head"><view><view class="head-title"><text>{{s==='database'?'MySQL 数据库':s==='redis'?'Redis 缓存':'HTTP 连接'}}</text><text class="badge" :class="{pending:pending(s)}">{{pending(s)?'待重启':'重启生效'}}</text></view><text class="head-subtitle">{{s==='database'?'持久化数据的连接与资源分配':s==='redis'?'影片列表缓存与连接池管理':'苹果 CMS 出站请求的超时与连接复用'}}</text></view><text class="badge">{{s==='database'?config.saved.database.mode.toUpperCase():s==='redis'?(config.active.redis?'已配置':'未启用'):'HTTP / HTTPS'}}</text></view>
<view class="card-body">
<template v-if="s==='database'"><view v-if="config.saved.database.mode!=='mysql'" class="empty-state">当前预览使用本地文件存储，未连接 MySQL。安装正式服务并配置数据库后，此处开放连接池调节与真实查询测试。</view><template v-else><view class="active-row"><text>数据库</text><text selectable>{{config.saved.database.address}} / {{config.saved.database.name}} · {{config.saved.database.username}}</text></view><text class="help">数据库地址和身份沿用安装配置；本区仅调整连接参数。</text></template><details><summary>高级参数 · 连接池与超时</summary><view class="parameter-grid"><view v-for="f in dbFields" :key="f[0]" class="field-row"><text class="field-label">{{f[1]}}</text><view class="field-content"><input v-model.number="forms.database[f[0]]" type="number" :aria-label="f[1]" :disabled="!!busy||config.saved.database.mode!=='mysql'"/></view></view></view><text class="help">连接存活或空闲回收填 0 表示不按该时长回收。空闲连接不得超过最大连接。</text></details></template>
<template v-if="s==='redis'"><view class="field-row"><text class="field-label">服务器地址</text><view class="field-content"><input v-model="forms.redis.address" :disabled="!!busy" aria-label="Redis服务器地址" placeholder="127.0.0.1:6379"/><text class="help">在运营服务所在服务器上发起连接，不是浏览器所在电脑。</text></view></view><view class="field-row"><text class="field-label">数据库编号</text><view class="field-content"><input v-model.number="forms.redis.db" type="number" :disabled="!!busy" aria-label="Redis数据库编号"/><text class="help">0–15，缓存键使用本服务专属前缀。</text></view></view><view class="field-row"><text class="field-label">连接密码</text><view class="field-content"><view class="segments"><button v-for="a in (['keep','replace','clear'] as const)" :key="a" :class="{selected:passwordAction===a}" :disabled="!!busy" @click="passwordAction=a">{{a==='keep'?'保留原密码':a==='replace'?'设置新密码':'使用无密码'}}</button></view><view v-if="passwordAction==='replace'" class="password-input" style="margin-top:12px"><input v-model="forms.redis.password" :password="!showPassword" :disabled="!!busy" aria-label="Redis新密码" placeholder="输入新密码"/><button :disabled="!!busy" @click="showPassword=!showPassword">{{showPassword?'隐藏':'显示'}}</button></view><text class="help">{{passwordAction==='keep'?(config.saved.redis?.passwordSet?'服务器已保存密码，页面不会回显。':'服务器未设置密码。'):passwordAction==='clear'?'保存后不发送密码，需 Redis 服务允许无密码访问。':'仅提交本次输入的新密码。'}}</text></view></view><details><summary>高级参数 · ACL 账户与缓存池</summary><view class="field-row"><text class="field-label">ACL 用户名</text><view class="field-content"><input v-model="forms.redis.username" :disabled="!!busy" aria-label="Redis ACL用户名" placeholder="留空使用默认账户"/></view></view><view class="parameter-grid"><view v-for="f in redisFields" :key="f[0]" class="field-row"><text class="field-label">{{f[1]}}</text><view class="field-content"><input v-model.number="forms.redis[f[0]]" type="number" :disabled="!!busy" :aria-label="'Redis '+f[1]"/></view></view></view><text class="help">连接池 1–500，缓存 5–3600 秒；最大空闲填 0 使用默认值。</text></details></template>
<template v-if="s==='http'"><view class="field-row"><text class="field-label">请求超时（秒）</text><view class="field-content"><input v-model.number="forms.http.timeoutSeconds" type="number" :disabled="!!busy" aria-label="HTTP请求超时"/><text class="help">单次请求的整体时限，范围 1–120 秒。连接测试另设 15 秒总时限。</text></view></view><details><summary>高级参数 · 连接复用与回收</summary><view class="parameter-grid"><view v-for="f in httpFields" :key="f[0]" class="field-row"><text class="field-label">{{f[1]}}</text><view class="field-content"><input v-model.number="forms.http[f[0]]" type="number" :disabled="!!busy" :aria-label="'HTTP '+f[1]"/></view></view></view><text class="help">单域名空闲连接不能超过全局空闲连接或单域名最大连接。</text></details></template>
<view class="active-row"><text>当前运行</text><text>{{describe(s)}}</text><text v-if="pending(s)" class="pending-value">保存值待重启</text></view>
<view class="card-footer"><text class="muted">{{s==='database'?'测试执行连接检查与 SELECT 1 查询。':s==='redis'?'测试执行 PING 和独立临时键读写、删除。':'测试使用表单参数实际请求已配置的苹果 CMS。'}}</text><view class="actions"><button :disabled="!!busy||(s==='database'&&config.saved.database.mode!=='mysql')" @click="run(s)">{{busy===s+'-test'?'连接测试中…':'测试连接'}}</button><button class="primary" :disabled="!!busy||!config.writable||(s==='database'&&config.saved.database.mode!=='mysql')" @click="run(s,true)">{{busy===s+'-save'?'保存中…':'保存配置'}}</button></view></view>
<text v-if="feedback[s]" class="notice connection-result" role="status">{{feedback[s]}}</text>
<view v-if="results[s]" class="connection-result"><text class="notice" :class="results[s]!.ok?'success':'error'" role="status">{{results[s]!.ok?'检测通过':'检测未通过'}} · {{results[s]!.message}}<text class="result-meta">{{results[s]!.latencyMs}} ms · {{results[s]!.checkedAt}}</text></text><CmsConnectionReport v-if="results[s]?.report" :report="results[s]!.report!" title="HTTP 实际请求明细"/></view>
</view></view></template></view></template>
<style scoped src="../styles/service-forms.css"></style>
